using System.IO;
namespace MapCorleon.Models;

public interface IEntity { int Id { get; set; } }
public sealed class Game : IEntity { public int Id { get; set; } public required string Name { get; set; } public ICollection<Map> Maps { get; set; } = []; }
public sealed class Map : IEntity { public int Id { get; set; } public int GameId { get; set; } public long? ExternalId { get; set; } public required string Name { get; set; } public string DisplayName => string.IsNullOrWhiteSpace(Game?.Name) ? Name : $"{Game.Name} / {Name}"; public Game? Game { get; set; } public MapConfig? Config { get; set; } public ICollection<Group> Groups { get; set; } = []; public ICollection<Timeline> Timelines { get; set; } = []; }
public sealed class MapConfig : IEntity { public int Id { get; set; } public int MapId { get; set; } public double MinLatitude { get; set; } public double MaxLatitude { get; set; } public double MinLongitude { get; set; } public double MaxLongitude { get; set; } public double DefaultZoom { get; set; } = 2; public string? TilePattern { get; set; } public int? MinZoom { get; set; } public int? MaxZoom { get; set; } public string? SpriteImagePath { get; set; } public Map? Map { get; set; } }
public sealed class Group : IEntity { public int Id { get; set; } public int MapId { get; set; } public long? ExternalId { get; set; } public required string Name { get; set; } public bool IsVisible { get; set; } = true; public Map? Map { get; set; } public ICollection<Category> Categories { get; set; } = []; }
public sealed class Category : IEntity { public int Id { get; set; } public int GroupId { get; set; } public long? ExternalId { get; set; } public required string Name { get; set; } public bool IsVisible { get; set; } = true; public string? IconKey { get; set; } public int? IconX { get; set; } public int? IconY { get; set; } public int? IconWidth { get; set; } public int? IconHeight { get; set; } public double? IconPixelRatio { get; set; } public Group? Group { get; set; } public ICollection<Location> Locations { get; set; } = []; }
public sealed class Location : IEntity { public int Id { get; set; } public int CategoryId { get; set; } public int? TimelineId { get; set; } public long? ExternalId { get; set; } public required string Title { get; set; } public string DescriptionMarkdown { get; set; } = ""; public double Latitude { get; set; } public double Longitude { get; set; } public bool IsCustom { get; set; } public Category? Category { get; set; } public Timeline? Timeline { get; set; } public ICollection<Media> Media { get; set; } = []; public ICollection<MarkedLocation> Marks { get; set; } = []; }
public sealed class Media : IEntity { public int Id { get; set; } public int LocationId { get; set; } public long? ExternalId { get; set; } public required string ContentHash { get; set; } public required string RelativePath { get; set; } public string? Caption { get; set; } public Location? Location { get; set; } }
public sealed class Timeline : IEntity { public int Id { get; set; } public int MapId { get; set; } public required string Name { get; set; } public int SortOrder { get; set; } public Map? Map { get; set; } public ICollection<Pin> Pins { get; set; } = []; public ICollection<MarkedLocation> Marks { get; set; } = []; public ICollection<Location> CustomLocations { get; set; } = []; }
public sealed class Pin : IEntity { public int Id { get; set; } public int TimelineId { get; set; } public int? LocationId { get; set; } public double Latitude { get; set; } public double Longitude { get; set; } public string? Title { get; set; } public Timeline? Timeline { get; set; } public Location? Location { get; set; } }
public sealed class MarkedLocation : IEntity { public int Id { get; set; } public int LocationId { get; set; } public int TimelineId { get; set; } public DateTime MarkedAtUtc { get; set; } = DateTime.UtcNow; public Location? Location { get; set; } public Timeline? Timeline { get; set; } }
public enum MarkFilter { All, Marked, Unmarked }
public sealed record AppSettings(string TileDirectory, string StorageDirectory, string DatabaseDirectory, MarkFilter Filter, Dictionary<int, bool> CategoryVisibility, TimeSpan TileMaxAge, string? CurrentMapName = null, int? CurrentTimelineId = null)
{
    public static AppSettings Default { get { var root = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "MapCorleon"); return new(Path.Combine(root, "tiles"), Path.Combine(root, "storage"), root, MarkFilter.All, [], TimeSpan.FromDays(30)); } }
}
